import { MarketingBody } from "./marketing-body";
import { PageHead, type PageHeadProps } from "./page-head";
import { SiteNav } from "./shared/site-nav";
import { trialModalHtml } from "./shared/trial-modal";

const wrap = { display: "contents" } as const;

/**
 * A page generated by scripts/port-businesses-pages.py: head tags, exact main/tail markup, shared nav/footer/pop-up.
 * footerInline: the footer is inside `main` (markup opened before it is closed after it), so it stays in the one exact
 * string, as in the blog pilot; the shared footer component is then not used.
 */
export function GeneratedPage({
  head,
  main,
  tail,
  footerInline = false,
}: {
  head: PageHeadProps;
  main: string;
  tail: string;
  footerInline?: boolean;
}) {
  return (
    <>
      <PageHead {...head} />
      {footerInline ? (
        <>
          <SiteNav />
          <div style={wrap} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: main }} />
          <div style={wrap} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: trialModalHtml() }} />
        </>
      ) : (
        <MarketingBody main={main} tail={tail} />
      )}
    </>
  );
}
